def _parse_tb_spec(spec):
    """解析 ``FILE[@TOP[@NAME]]``；名称/顶层省略时返回 None 由 TestSpec 补。"""
    parts = spec.split("@")
    if len(parts) > 3 or not parts[0]:
        raise ValueError(f"测试台规格非法：{spec!r}（应为 FILE[@TOP[@NAME]]）")
    if len(parts) >= 2 and not parts[1].strip():
        raise ValueError(f"测试台顶层名为空：{spec!r}")
    if len(parts) == 3 and not parts[2].strip():
        raise ValueError(f"测试台名称为空：{spec!r}")
    path = parts[0]
    top = parts[1] if len(parts) >= 2 else None
    name = parts[2] if len(parts) == 3 else None
    return path, top, name

