def _plan_tb_dirs(specs):
    """为各测试台规划唯一且稳定的子目录名。

    常规情况直接使用清洗后的逻辑名；仅当不同逻辑名清洗后撞名时，给撞名者
    追加由逻辑名导出的稳定短哈希后缀。同名输入在任何机器上都得到同一结果。
    """
    base = {id(s): _safe_dir_name(s.name) for s in specs}
    used = {}
    result = {}
    for s in specs:
        candidate = base[id(s)]
        if candidate in used and used[candidate] is not s.name:
            # 已有别的逻辑名占用该目录名：两者都加稳定短哈希以彻底消歧。
            owner = used[candidate]
            suffix_owner = hashlib.sha1(owner.encode("utf-8")).hexdigest()[:8]
            suffix_me = hashlib.sha1(s.name.encode("utf-8")).hexdigest()[:8]
            result[owner] = f"{_safe_dir_name(owner)}_{suffix_owner}"
            candidate = f"{_safe_dir_name(s.name)}_{suffix_me}"
        used[candidate] = s.name
        result.setdefault(s.name, candidate)
    return result

